import urllib.parse
from typing import Dict, Any, List, Tuple

def canonicalize_nested_query(params: Dict[str, Any]) -> str:
    if not isinstance(params, dict):
        raise TypeError('Params must be a dictionary')

    def _flatten(val, prefix=''):
        items = []
        if isinstance(val, dict):
            for k in sorted(val.keys(), key=lambda x: str(x)):
                sub_prefix = f'{prefix}[{k}]' if prefix else str(k)
                items.extend(_flatten(val[k], sub_prefix))
        elif isinstance(val, (list, tuple)):
            for idx, item in enumerate(val):
                sub_prefix = f'{prefix}[{idx}]'
                items.extend(_flatten(item, sub_prefix))
        elif val is None:
            pass
        elif isinstance(val, bool):
            items.append((prefix, 'true' if val else 'false'))
        else:
            items.append((prefix, str(val)))
        return items

    flattened = _flatten(params)
    flattened.sort(key=lambda pair: pair[0])

    parts = []
    for k, v in flattened:
        enc_k = urllib.parse.quote(k, safe='~_.-[]')
        enc_v = urllib.parse.quote(v, safe='~_.-')
        parts.append(f'{enc_k}={enc_v}')
    return '&'.join(parts)
